"""Local, self-contained renderer for the frozen DXY gold entry-veto screen.

This file never fetches data, connects to MT5, changes strategy inputs, or
computes/selects new filter parameters.  Portfolio metrics come from RESULTS.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8-sig"))


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def verified_receipt(path, result_sha):
    """Never display a PASS badge from an unbound or stale audit receipt."""
    if not path.exists():
        return {"status": "PENDING", "explanation": "Independent outcome verification receipt not yet present."}
    receipt = read(path)
    bound = receipt.get("results_sha256", receipt.get("result_sha256"))
    if receipt.get("status") != "PASS" or bound != result_sha:
        return {"status": "NOT BOUND", "explanation": "No matching PASS receipt for this exact RESULTS.json. Do not treat these outcomes as independently verified."}
    return {"status": "PASS", "checks": receipt.get("checks", receipt.get("checked")),
            "results_sha256": result_sha}


def payload():
    plan, inputs, result = (read(ROOT / name) for name in ("PLAN.json", "INPUTS.json", "RESULTS.json"))
    assert result["plan_sha256"] == digest(ROOT / "PLAN.json"), "Result/plan hash mismatch"
    assert result["inputs_sha256"] == digest(ROOT / "INPUTS.json"), "Result/input hash mismatch"
    assert result["frozen_sha256"] == digest(ROOT / "FROZEN.json"), "Result/freeze hash mismatch"
    assert set(plan["scope"]) == set(inputs["sources"])
    expected_combos = {(p["id"], ea, cost, view)
                       for p in plan["periods"] for ea in (*plan["scope"], "combined")
                       for cost in ("recorded", "stress")
                       for view in ("baseline", "primary", "secondary")}
    combos = {(r["period"], r["ea"], r["cost"], r["view"]) for r in result["results"]}
    assert len(result["results"]) == len(expected_combos)
    assert combos == expected_combos, "Duplicate/missing comparison combinations"
    assert len({r["key"] + ":" + str(int(r["position_id"])) for r in inputs["rows"]}) == len(inputs["rows"]), "Duplicate source position"
    assert {f["id"] for f in result["features"]} == {r["key"] + ":" + str(int(r["position_id"])) for r in inputs["rows"]}, "Source/feature position mismatch"
    assert len(result["features"]) == len(inputs["rows"]), "Duplicate/missing feature"
    source_audit = read(ROOT / "SOURCE AUDIT.json")
    assert source_audit["status"] == "PASS", "Source accounting is not verified"
    assert source_audit["validated_rows"] == len(inputs["rows"]), "Source audit/row mismatch"
    assert set(source_audit["counts"]) == set(plan["scope"]), "Source audit/scope mismatch"
    return dict(plan=plan, results=result["results"], features=result["features"],
                rows=inputs["rows"], sources=inputs["sources"], exclusions=inputs["exclusions"],
                data_audit=result["data_audit"], source_audit=source_audit,
                verification=verified_receipt(ROOT / "VERIFICATION.json", digest(ROOT / "RESULTS.json")),
                results_sha256=digest(ROOT / "RESULTS.json"))


